/* function is accepted but ignored: drawing is always GXcopy. Lines honour
 * line_width, cap_style and join_style (width 0 or 1 draws a plain
 * one-pixel line). plane_mask is accepted and ignored. */
typedef struct {
  unsigned long foreground;
  unsigned long background;
  int function;
  unsigned long plane_mask;
  int line_width;
  int cap_style;
  int join_style;
  /* Accepted and ignored: a polygon is always filled even-odd, and always
   * solid (no fill style or stipple). */
  int fill_rule;
  int fill_style;
  Pixmap stipple;
} XGCValues;

typedef struct {
  unsigned long pixel;
  unsigned short red, green, blue;
  char flags;
  char pad;
} XColor;

typedef struct {
  int x, y;
  int width, height;
  int depth;
  Visual *visual;
  Screen *screen;
  Colormap colormap;
  long your_event_mask;
} XWindowAttributes;

typedef struct {
  short x, y;
} XPoint;

/* A string's or a glyph's extent: X's layout. */
typedef struct {
  short lbearing, rbearing, width, ascent, descent;
  unsigned short attributes;
} XCharStruct;

typedef struct {
  short x, y;
  unsigned short width, height;
} XRectangle;

typedef struct {
  short x, y;
  unsigned short width, height;
  short angle1, angle2;
} XArc;

typedef struct {
  short x1, y1, x2, y2;
} XSegment;

typedef unsigned long KeySym;
/* The values X uses. No key event ever arrives, so a hack only compares
 * against them. */
#define XK_Left 0xFF51
