285	analogtv_alloc_image(analogtv *it)
286	{
287	  /* On failure, it->image is NULL. */
288	
289	  unsigned bits_per_pixel = visual_pixmap_depth(it->screen, it->xgwa.visual);
290	  unsigned align = thread_memory_alignment(it->dpy) * 8 - 1;
291	  /* Width is in bits. */
292	  unsigned width = (it->usewidth * bits_per_pixel + align) & ~align;
293	
294	  it->image=create_xshm_image(it->dpy, it->xgwa.visual, it->xgwa.depth,
295	                              ZPixmap, &it->shm_info,
296	                              width / bits_per_pixel, it->useheight);
297	
298	  if (it->image) {
299	    memset (it->image->data, 0, it->image->height * it->image->bytes_per_line);
300	  } else {
301	    /* Not enough memory. Maybe try a smaller window. */
302	    fprintf(stderr, "analogtv: %s\n", strerror(ENOMEM));
303	  }
304	}
