308	analogtv_configure(analogtv *it)
309	{
310	  int oldwidth=it->usewidth;
311	  int oldheight=it->useheight;
312	  int wlim,hlim,height_diff;
313	
314	  /* If the window is very small, don't let the image we draw get lower
315	     than the actual TV resolution (266x200.)
316	
317	     If the aspect ratio of the window is close to a 4:3 or 16:9 ratio --
318	     or if it is a completely weird aspect ratio --
319	     then scale the image to exactly fill the window.
320	
321	     Otherwise, center the image either horizontally or vertically,
