/* Every XImage holds canvas-order pixels, whatever its depth: the values
 * XAllocColor, GC colours and XGetImage hand out. XPutImage copies them as
 * they are. */
static uint16_t xshim_image_pixel(XImage *im, int x, int y) {
  return (uint16_t)XGetPixel(im, x, y);
}

int XPutImage(Display *dpy, Drawable d, GC gc, XImage *im, int src_x,
              int src_y, int dst_x, int dst_y, unsigned int w,
              unsigned int h) {
  Canvas *dst = xshim_target(dpy, d);
  if (!dst) return xshim_bitmap_put_image(dpy, d, gc, im, src_x, src_y, dst_x, dst_y, w, h), 0;
  if (!im || !im->data) return 0;
  if (im->bits_per_pixel == 1 && !gc) return 0;
  const int64_t i0 = max_i64(0, max_i64(-(int64_t)src_x, -(int64_t)dst_x));
  const int64_t j0 = max_i64(0, max_i64(-(int64_t)src_y, -(int64_t)dst_y));
  const int64_t i1 = min_i64(w, min_i64((int64_t)im->width - src_x,
                                        (int64_t)dst->w - dst_x));
  const int64_t j1 = min_i64(h, min_i64((int64_t)im->height - src_y,
                                        (int64_t)dst->h - dst_y));
  if (i1 <= i0 || j1 <= j0) return 0;
  if (im->bits_per_pixel == 16) {
    for (int64_t j = j0; j < j1; j++)
      memcpy(&dst->px[(dst_y + j) * dst->w + dst_x + i0],
             im->data + (src_y + j) * (int64_t)im->bytes_per_line +
                 (src_x + i0) * 2,
             (size_t)(i1 - i0) * sizeof(uint16_t));
  } else if (im->bits_per_pixel == 1) {
    for (int64_t j = j0; j < j1; j++)
      for (int64_t i = i0; i < i1; i++)
        dst->px[(dst_y + j) * dst->w + dst_x + i] =
            (uint16_t)(XGetPixel(im, (int)(src_x + i), (int)(src_y + j))
                           ? gc->foreground
                           : gc->background);
  } else {
    for (int64_t j = j0; j < j1; j++)
      for (int64_t i = i0; i < i1; i++)
        dst->px[(dst_y + j) * dst->w + dst_x + i] =
            xshim_image_pixel(im, (int)(src_x + i), (int)(src_y + j));
  }
  canvas_mark_dirty(dst, (int)(dst_x + i0), (int)(dst_y + j0), (int)(i1 - i0),
                    (int)(j1 - j0));
  return 0;
}

